          border-color:${accent};
          color:${accent};
          background:
            radial-gradient(
              circle,
              ${glow}0.18),
              rgba(5,18,31,0.48) 61%,
              transparent 63%
            );
          box-shadow:
            0 0 24px ${glow}0.37),
            inset 0 0 24px ${glow}0.08);
        "
      >
        <ha-icon icon="mdi:key-variant"></ha-icon>
      </div>

      <div class="hv-lock-state" style="color:${accent};">
        ${title}
      </div>

      <div class="hv-lock-message">
        ${message}
      </div>

      <div class="hv-lock-counts">

        <div class="hv-count hv-count-alert">
          <ha-icon icon="mdi:lock-open-alert-outline"></ha-icon>
          <div>
            <strong>${unlocked}</strong>
            <span>UNLOCKED</span>
          </div>
        </div>

        <div class="hv-count-divider"></div>

        <div class="hv-count hv-count-alarm-home">
          <ha-icon icon="mdi:door-open"></ha-icon>
          <div>
            <strong>${openSensors}</strong>
            <span>OPEN</span>
          </div>
        </div>

      </div>
    </div>
  `;
]]]

